'use strict';

// MODULES //

var min = require( '@stdlib/stats/array/min' );


// MAIN //

/**
* Returns defaults.
*
* @private
* @param {NumericArray} extent - two-element array with the minimum and maximum values of the bin range
* @returns {Object} default options
*
* @example
* var ext = [ 0, 10 ];
*
* var o = defaults( ext );
* // returns {...}
*/
function defaults( extent ) {
	return {
		// Value in the binned domain at which to anchor bin boundaries:
		'anchor': min( extent ),

		// Output field names for the start and end bin values:
		'as': [ 'bin0', 'bin1' ],

		// Number base for automatic bin determination:
		'base': 10,

		// Allowable bin step sub-divisions:
		'divide': [ 5, 2 ],

		// Boolean indicating whether to output start and end bin values:
		'interval': 'true',

		// Maximum number of bins:
		'maxbins': 20,

		// Minimum allowed bin step size:
		'minstep': 0,

		// Boolean indicating attempt to make bin boundaries "nice":
		'nice': true,

		// Span over which to generate bin boundaries:
		'span': extent[1] - extent[0]
	};
}


// EXPORTS //

module.exports = defaults;
